import json
import os
import subprocess
import time
import uuid
from pathlib import Path

import modal

from spindle.providers.modal.miles_image import image

app = modal.App('spindle-nccl-suspend-minimal-1106')
image = image.add_local_file('/tmp/nccl_suspend_worker.py', '/root/nccl_suspend_worker.py')


@app.cls(image=image, gpu='H100!:2', cpu=8, memory=32768,
         env={'MASTER_ADDR': '127.0.0.1', 'MASTER_PORT': '29983',
              'NCCL_NVLS_ENABLE': '0', 'NCCL_SOCKET_IFNAME': 'lo',
              'NCCL_DEBUG': 'INFO', 'NCCL_DEBUG_FILE': '/tmp/nccl.%p.log'},
         max_containers=1, single_use_containers=True, retries=0,
         startup_timeout=600, timeout=120, enable_memory_snapshot=True,
         experimental_options={'enable_gpu_snapshot': True})
class Probe:
    def read_all(self):
        rows = []
        for child in self.children:
            while True:
                line = child.stdout.readline()
                if not line:
                    raise RuntimeError(f'worker exited: {child.poll()}')
                if line.startswith('CONTROL_RESULT '):
                    rows.append(json.loads(line.removeprefix('CONTROL_RESULT ')))
                    break
                print(line, end='', flush=True)
        return rows

    def command(self, name):
        for child in self.children:
            child.stdin.write(name + '\n')
            child.stdin.flush()
        return self.read_all()

    @modal.enter(snap=True)
    def initialize(self):
        self.init_id = uuid.uuid4().hex
        self.creator = os.environ['MODAL_TASK_ID']
        self.children = [subprocess.Popen(
            ['python', '/root/nccl_suspend_worker.py', str(rank)],
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True, bufsize=1,
        ) for rank in range(2)]
        self.before = self.read_all()
        self.command('suspend')
        assert self.command('resume') == self.before
        print('MINIMAL_CONTROL_PASSED', json.dumps(self.before), flush=True)
        self.command('suspend')
        print('MINIMAL_READY_TO_CAPTURE', self.init_id, flush=True)

    @modal.enter(snap=False)
    def restore(self):
        print('MINIMAL_RESUME_BEGIN', flush=True)
        self.after = self.command('resume')
        assert self.after == self.before
        print('MINIMAL_RESUME_PASSED', flush=True)

    @modal.method()
    def verify(self):
        return {'init_id': self.init_id, 'creator': self.creator,
                'task': os.environ['MODAL_TASK_ID'], 'ranks': self.after,
                'nccl_logs': {p.name: p.read_text() for p in Path('/tmp').glob('nccl.*.log')}}


@app.local_entrypoint()
def main():
    cls = modal.Cls.from_name('spindle-nccl-suspend-minimal-1106', 'Probe')
    call = cls().verify.spawn()
    print('MINIMAL_CALL', call.object_id, flush=True)
    try:
        row = call.get(timeout=480)
        Path('/tmp/nccl-suspend-minimal.json').write_text(json.dumps(row, indent=2))
        print('MINIMAL_RESULT', json.dumps({k:v for k,v in row.items() if k != 'nccl_logs'}), flush=True)
    except BaseException:
        call.cancel(terminate_containers=True)
        raise

